select sig from (select p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' sig from pg_proc p where p.pronamespace='public'::regnamespace) old_f left join (values ('_default_invoice_prefix(_name text)'),('_new_session_token(_customer_id uuid, _store_id uuid, _ua text, _ip text)'),('_normalize_phone(_phone text)'),('claim_messenger_job(_job_id uuid, _wake_token uuid)'),('customer_change_password(_token text, _store_id uuid, _old text, _new text)'),('customer_create_return(_token text, _store_id uuid, _order_id uuid, _type text, _reason text, _items jsonb, _images text[], _replacement_note text, _note text)'),('customer_create_return_v2(_token text, _store_id uuid, _order_id uuid, _kind text, _type text, _reason text, _note text, _lines jsonb, _replacement_items jsonb, _images text[], _amounts jsonb)'),('customer_from_token(_token text, _store_id uuid)'),('customer_list_returns(_token text, _store_id uuid, _order_id uuid)'),('customer_list_returns_v2(_token text, _store_id uuid, _order_id uuid)'),('customer_login(_store_id uuid, _identifier text, _password text, _ua text, _ip text)'),('customer_logout(_token text)'),('customer_request_password_reset(_store_id uuid, _identifier text)'),('customer_reset_password(_store_id uuid, _token text, _new text)'),('customer_signup(_store_id uuid, _name text, _email text, _phone text, _password text, _ua text, _ip text)'),('customer_update_profile(_token text, _store_id uuid, _name text, _email text, _phone text)'),('delete_email(queue_name text, message_id bigint)'),('domain_token_exists(_token text)'),('email_queue_dispatch()'),('email_queue_wake()'),('enqueue_email(queue_name text, payload jsonb)'),('enqueue_order_notification()'),('expire_trials()'),('format_merchant_code(_n bigint)'),('generate_invoice_no(_store_id uuid)'),('get_active_store_gateway_public(_store_id uuid)'),('get_billing_discounts()'),('get_custom_gateway_public(_id uuid)'),('get_customer_subscriptions(_token text, _store_id uuid)'),('get_fraud_public_status()'),('get_messenger_daily_stats(_store_id uuid)'),('get_my_active_ads()'),('get_platform_branding()'),('get_platform_footer()'),('get_product_reviews(_product_id uuid)'),('get_public_courier_providers()'),('get_public_delivery_zones(_store_id uuid)'),('get_public_landing_page(_slug text)'),('get_public_order(_order_id uuid)'),('get_public_payment_gateways()'),('get_public_return_settings(_store_id uuid)'),('get_public_service_order(_order_id uuid)'),('get_public_store_by_slug(_slug text)'),('get_public_subscription_order(_order_id uuid)'),('get_store_bestsellers(_store_id uuid, _limit integer)'),('get_store_legal_page(_slug text, _page text)'),('get_store_page(_slug text, _page_key text)')) v(s) on v.s=old_f.sig where v.s is null;